var state={people:[],people_all:[],areas:[],areas_all:[],today:[],suggested:[],upcoming:[],tasks:[],inventory:[],inventory_all:[],shopping_list:[],events:[],external_events:[],agenda_events:[],calendar_subscriptions:[],event_today:[],event_upcoming:[],alerts_due:[],activity:[],vacation:{active:false,started_on:null,return_date:null,resume_mode:"continue_cycle",excluded_area_ids:[]},telegram:{token_configured:false,token_source:"none",token_editable:true,chat_id:null,chat_title:"",bot_username:"",poll_seconds:60,last_contact_at:null,worker_running:false},settings:{version:"",runtime:{timezone:"Europe/Zurich",telegram_poll_seconds:60,ical_sync_minutes:30,max_attachment_mb:20},telegram:{},calendars:{subscription_count:0},attachments:{count:0,max_mb:20},integrations:{gastos_comida:{configured:false,url:"",source:"none",last_ok_at:null,last_error:""}}},history:[],stats:[],last_undo:null};var view="board";var taskSection="tasks";var dragged=null;var areaDraggedTask=null;var dropBusy=false;var suggestMinutes=null;var mobileBoardIndex=2;var boardScrollRAF=null;var toastTimer=null;var browserNotified={};
var homeGastosSummary=null;var homeGastosLoading=false;var homeGastosLoaded=false;var homeGastosError="";var shoppingPlan=null;var shoppingPlanLoading=false;var shoppingPlanLoaded=false;
var views=[["board","Tablero","▦"],["tasks","Tareas","☰"],["events","Agenda","📅"],["areas","Áreas","⌂"],["people","Personas","👥"],["gastos","Gastos","🛒"],["history","Historial","↺"],["settings","Configuración","⚙"]];
function esc(s){return String(s==null?"":s).replace(/[&<>"']/g,function(c){return({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"})[c]})}
function apiUrl(url){if(url.indexOf("/api/")!==0)return url;try{var params=new URLSearchParams(window.location.search);var proxyToken=params.get("_sm_au_");if(proxyToken){var sep=url.indexOf("?")>=0?"&":"?";return url+sep+"_sm_au_="+encodeURIComponent(proxyToken)}}catch(e){}return url}
function parseApiResponse(raw,r,url){if(!raw)return{};try{return JSON.parse(raw)}catch(e){var ct=(r.headers&&r.headers.get)?(r.headers.get("content-type")||""):"";var looksHtml=ct.indexOf("text/html")>=0||/^\s*</.test(raw);if(looksHtml)throw new Error("La llamada "+url+" devolvió HTML en lugar de datos JSON. Un proxy o filtro de red puede estar interceptando la API.");throw new Error("La llamada "+url+" devolvió una respuesta no válida.")}}
async function api(url,opt){var target=apiUrl(url),options=Object.assign({headers:{"Content-Type":"application/json"},cache:"no-store",credentials:"same-origin"},opt||{}),r;try{r=await fetch(target,options)}catch(e){throw new Error("No se pudo conectar con la API en "+url+". Comprueba la conexión o el proxy de red.")}var raw=await r.text(),x=parseApiResponse(raw,r,url);if(!r.ok)throw new Error(x.detail||("Error HTTP "+r.status));return x}
async function apiForm(url,form){var target=apiUrl(url),r;try{r=await fetch(target,{method:"POST",body:form,cache:"no-store",credentials:"same-origin"})}catch(e){throw new Error("No se pudo subir el archivo.")}var raw=await r.text(),x=parseApiResponse(raw,r,url);if(!r.ok)throw new Error(x.detail||("Error HTTP "+r.status));return x}
function renderLoadError(err){try{tabs()}catch(e){}var main=document.getElementById("main");if(!main)return;var hasProxy=false;try{hasProxy=new URLSearchParams(window.location.search).has("_sm_au_")}catch(e){}main.innerHTML='<div class="pagehead"><div><h1>No se pudo cargar Casa Tareas</h1><div class="subtitle">El servidor responde, pero el navegador no pudo leer correctamente la API.</div></div></div><div class="settings-grid"><section class="settings-card wide"><h2>⚠️ Diagnóstico</h2><div class="settings-warning">'+esc(err&&err.message?err.message:String(err))+'</div>'+(hasProxy?'<div class="settings-note">Esta sesión contiene <code>_sm_au_</code>, un parámetro que puede ser añadido por un proxy corporativo. Casa Tareas lo está propagando también a las llamadas de la API.</div>':'')+'<div class="settings-actions"><button class="primary" onclick="load()">Reintentar</button><button class="ghost" onclick="window.location.href=apiUrl(\'/api/health\')">Abrir /api/health</button><button class="ghost" onclick="window.location.href=apiUrl(\'/api/state\')">Abrir /api/state</button></div><div class="settings-note">Si <code>/api/state</code> muestra JSON con tus tareas pero esta pantalla sigue apareciendo, prueba una ventana InPrivate del navegador corporativo.</div></section></div>'}
async function load(){try{state=await api("/api/state");render()}catch(e){console.error("Casa Tareas load error",e);renderLoadError(e)}}
function fmtDate(s){if(!s)return"";var d=new Date(s.length===10?s+"T12:00:00":s);return new Intl.DateTimeFormat("es",{day:"numeric",month:"short"}).format(d)}
function localDateValue(addDays){var d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+(addDays||0));return d.getFullYear()+"-"+pad2(d.getMonth()+1)+"-"+pad2(d.getDate())}
function dueText(t){if(t.paused||!t.next_due)return"";var a=new Date(t.next_due+"T12:00:00"),b=new Date();b.setHours(12,0,0,0);var n=Math.round((a-b)/86400000);if(n<0)return Math.abs(n)+" d pendiente";if(n===0)return"Hoy";if(n===1)return"Mañana";return"En "+n+" días"}
function tabs(){var h="",b="";views.forEach(function(v){h+='<button class="tab '+(view===v[0]?"active":"")+'" onclick="go(\''+v[0]+'\')">'+v[1]+"</button>";if(v[0]!=="settings")b+='<button class="'+(view===v[0]?"active":"")+'" onclick="go(\''+v[0]+'\')"><div>'+v[2]+"</div>"+v[1]+"</button>"});document.querySelector(".tabs").innerHTML=h;document.getElementById("bottom").innerHTML=b;updateUndoButton()}
function go(v){view=v;render()}
function updateUndoButton(){var b=document.getElementById("undoTop");if(!b)return;if(state.last_undo){b.classList.remove("hidden");b.textContent=window.matchMedia("(max-width:760px)").matches?"↶":"↶ Deshacer"}else b.classList.add("hidden")}
function showUndo(message,undoId){var t=document.getElementById("toast");if(!t)return;if(toastTimer)clearTimeout(toastTimer);t.innerHTML='<span>'+esc(message)+'</span>'+(undoId?'<button onclick="undoById('+undoId+')">Deshacer</button>':'');t.classList.remove("hidden");toastTimer=setTimeout(function(){t.classList.add("hidden")},12000)}
async function undoById(id){try{var r=await api("/api/undo/"+id,{method:"POST"});await load();showUndo("Deshecho: "+(r.undone||"último cambio"),null)}catch(e){alert(e.message)}}
async function undoLatest(){if(state.last_undo)await undoById(state.last_undo.id)}
function render(){tabs();if(view==="board")renderBoard();if(view==="tasks")renderTasks();if(view==="events")renderEvents();if(view==="areas")renderAreas();if(view==="people")renderPeople();if(view==="gastos"&&typeof renderGastos==="function")renderGastos();if(view==="history")renderHistory();if(view==="settings")renderSettings();renderDueAlerts();notifyBrowserAlerts()}
function pad2(n){return String(n).padStart(2,"0")}
function datetimeLocalValue(value){var d=value?new Date(value):new Date(Date.now()+86400000);if(!value)d.setMinutes(0,0,0);return d.getFullYear()+"-"+pad2(d.getMonth()+1)+"-"+pad2(d.getDate())+"T"+pad2(d.getHours())+":"+pad2(d.getMinutes())}
function fmtEventDate(value){var d=new Date(value);return new Intl.DateTimeFormat("es",{weekday:"short",day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}).format(d)}
function fmtAgendaEvent(e){var d=new Date(e.event_at);if(e.all_day)return new Intl.DateTimeFormat("es",{weekday:"short",day:"numeric",month:"short"}).format(d)+" · todo el día";return fmtEventDate(e.event_at)}
function reminderLabel(minutes){if(minutes===0)return"A la hora";if(minutes<60)return minutes+" min antes";if(minutes%1440===0)return(minutes/1440)+" d antes";if(minutes%60===0)return(minutes/60)+" h antes";return minutes+" min antes"}
function eventCard(e,compact){var area=e.area?'<span class="pill">'+esc(e.area.icon||"⌂")+" "+esc(e.area.name)+'</span>':"";var reminders=(e.reminders||[]).map(function(m){return'<span class="pill">🔔 '+esc(reminderLabel(m))+'</span>'}).join("");var source=e.external?'<span class="pill external-pill">↗ '+esc(e.calendar_name||"Calendario externo")+'</span>':"";var location=e.location?'<span class="pill">📍 '+esc(e.location)+'</span>':"";var actions=compact||e.external?"":'<div class="actions"><button class="ghost" onclick="openEvent('+e.id+')">Editar</button><button class="danger" onclick="deleteEvent('+e.id+')">Eliminar</button></div>';return'<div class="event-card '+(compact?"compact":"")+'"><div class="icon">'+(e.external?"🗓️":"📅")+'</div><div><div class="title">'+esc(e.title)+'</div><div class="event-time">'+esc(fmtAgendaEvent(e))+'</div><div class="desc">'+esc(e.description||"")+'</div><div class="meta">'+area+source+location+reminders+'</div></div>'+actions+'</div>'}
function renderDueAlerts(){var main=document.getElementById("main");if(!main||!state.alerts_due||!state.alerts_due.length)return;var h='<div class="alert-panel"><strong>🔔 Avisos pendientes</strong>'+state.alerts_due.map(function(a){var area=a.area?esc(a.area.name)+" · ":"";return'<div class="alert-row"><div class="alert-main"><span>📅</span><div><strong>'+esc(a.title)+'</strong><div class="muted">'+area+esc(fmtEventDate(a.event_at))+' · '+esc(reminderLabel(a.reminder_minutes))+'</div></div></div><div class="alert-actions"><button class="secondary" onclick="ackEventReminder('+a.event_id+','+a.reminder_minutes+')">Visto</button></div></div>'}).join("")+'</div>';main.insertAdjacentHTML("afterbegin",h)}
async function ackEventReminder(eventId,minutes){try{await api("/api/events/"+eventId+"/reminders/"+minutes+"/ack",{method:"POST"});await load()}catch(e){alert(e.message)}}
function notifyBrowserAlerts(){if(!state.alerts_due||!state.alerts_due.length||!("Notification" in window)||Notification.permission!=="granted")return;state.alerts_due.forEach(function(a){var key=a.event_id+":"+a.reminder_minutes;if(browserNotified[key])return;browserNotified[key]=true;try{new Notification("Casa Tareas · "+a.title,{body:(a.area?a.area.name+" · ":"")+fmtEventDate(a.event_at)})}catch(e){}})}
async function requestBrowserNotifications(){if(!("Notification" in window)){alert("Este navegador no admite notificaciones.");return}if(!window.isSecureContext){alert("Las notificaciones del navegador requieren HTTPS o abrir la app desde localhost. Los avisos dentro de Casa Tareas seguirán funcionando.");return}var result=await Notification.requestPermission();if(result==="granted"){notifyBrowserAlerts();alert("Avisos del navegador activados mientras Casa Tareas esté abierta.")}else alert("No se concedió permiso para notificaciones.")}
function durationLabel(minutes){if(!minutes)return"";if(minutes<60)return minutes+" min";if(minutes%60===0)return(minutes/60)+" h";return Math.floor(minutes/60)+" h "+(minutes%60)+" min"}
function needClass(score){if(score>=100)return"need-due";if(score>=70)return"need-good";if(score>=40)return"need-soon";return"need-soft"}
function needMeter(t){if(t.need_score==null)return"";var shown=Math.min(100,Math.max(0,t.need_score));return '<div class="need-row '+needClass(t.need_score)+'"><div class="need-track"><div class="need-fill" style="width:'+shown+'%"></div></div><span class="need-label">'+esc(t.need_label)+' · '+t.need_score+'%</span></div>'}
function suggestionCard(t){var area=t.area?esc(t.area.icon||"⌂")+" "+esc(t.area.name):"Sin área";var duration=t.estimated_minutes?"⏱ "+durationLabel(t.estimated_minutes):"⏱ Sin estimar";return '<div class="suggestion-card"><div class="suggestion-top"><div class="icon">'+esc(t.icon)+'</div><div><div class="title">'+esc(t.title)+'</div><div class="muted">'+area+' · '+duration+'</div></div></div>'+needMeter(t)+'<div class="actions"><button class="secondary" onclick="addToday('+t.id+')">+ Hoy</button><button class="ghost" onclick="editTask('+t.id+')">Editar</button></div></div>'}
function filteredSuggestions(){var list=state.suggested||[];if(suggestMinutes==null)return list;return list.filter(function(t){return t.estimated_minutes!=null&&t.estimated_minutes<=suggestMinutes})}
function setSuggestMinutes(value){suggestMinutes=value;renderBoard()}
function suggestionsPanel(){var list=filteredSuggestions();var h='<section class="suggestions-panel"><div class="suggestions-head"><div><div class="suggestions-title">✨ Sugeridas ahora</div><div class="suggestions-help">Tareas recurrentes cerca de su ciclo. Nada entra en Hoy automáticamente.</div></div><div class="suggest-filter"><button class="'+(suggestMinutes==null?"active":"")+'" onclick="setSuggestMinutes(null)">Todas</button><button class="'+(suggestMinutes===10?"active":"")+'" onclick="setSuggestMinutes(10)">≤10 min</button><button class="'+(suggestMinutes===20?"active":"")+'" onclick="setSuggestMinutes(20)">≤20 min</button><button class="'+(suggestMinutes===30?"active":"")+'" onclick="setSuggestMinutes(30)">≤30 min</button><button class="'+(suggestMinutes===60?"active":"")+'" onclick="setSuggestMinutes(60)">≤1 h</button></div></div><div class="suggestions-strip">'+(list.length?list.map(suggestionCard).join(""):'<div class="empty">'+(suggestMinutes==null?"No hay tareas que necesiten atención ahora.":"No hay sugerencias que quepan en ese tiempo con duración estimada.")+'</div>')+'</div></section>';return h}
function taskSupplyPicker(t){var selected={};(t&&t.supplies||[]).forEach(function(i){selected[i.id]=true});if(!(state.inventory||[]).length)return'<div class="muted">No hay productos en Inventario. Puedes crearlos desde Tareas → Inventario y Comprar.</div>';return'<div class="supply-picker">'+state.inventory.map(function(i){return'<label class="supply-choice"><input type="checkbox" name="supply_id" value="'+i.id+'" '+(selected[i.id]?"checked":"")+'> <span>'+esc(i.name)+' <span class="muted">· '+esc(stockLabel(i.stock_status))+'</span></span></label>'}).join("")+'</div>'}
function fileSizeLabel(bytes){if(bytes<1024)return bytes+" B";if(bytes<1024*1024)return Math.round(bytes/1024)+" KB";return(bytes/(1024*1024)).toFixed(1)+" MB"}
function documentsBox(entityType,item){if(!item||!item.id)return"";var docs=item.attachments||[];var inputId="attach-"+entityType+"-"+item.id;return'<div class="document-box"><div><strong>📎 Documentos</strong><div class="muted">PDF, imágenes, facturas, garantías, contratos o manuales. Máximo 20 MB por archivo.</div></div><div class="document-list">'+(docs.length?docs.map(function(d){return'<div class="document-row"><div><a href="/api/attachments/'+d.id+'/download">'+esc(d.original_name)+'</a><div class="muted">'+esc(fileSizeLabel(d.size_bytes))+'</div></div><button class="danger" type="button" onclick="deleteAttachment('+d.id+',\''+entityType+'\','+item.id+')">Eliminar</button></div>'}).join(""):'<div class="muted">Sin documentos adjuntos.</div>')+'</div><div class="actions"><input id="'+inputId+'" type="file"><button class="secondary" type="button" onclick="uploadAttachment(\''+entityType+'\','+item.id+',\''+inputId+'\')">Subir documento</button></div></div>'}
async function uploadAttachment(entityType,id,inputId){var input=document.getElementById(inputId);if(!input||!input.files||!input.files[0]){alert("Selecciona primero un archivo.");return}var form=new FormData();form.append("entity_type",entityType);form.append("entity_id",String(id));form.append("file",input.files[0]);try{await apiForm("/api/attachments",form);await load();if(entityType==="task")openTask(id);else openArea(id)}catch(e){alert(e.message)}}
async function deleteAttachment(attachmentId,entityType,entityId){if(!confirm("¿Eliminar este documento?"))return;try{await api("/api/attachments/"+attachmentId,{method:"DELETE"});await load();if(entityType==="task")openTask(entityId);else openArea(entityId)}catch(e){alert(e.message)}}
function taskMeta(t){var m='<span class="pill">'+esc(t.category)+'</span>';m+='<span class="pill">'+(t.task_type==="management"?"🧠 Gestión":"🧹 Ejecución")+'</span>';if(t.estimated_minutes)m+='<span class="pill">⏱ '+esc(durationLabel(t.estimated_minutes))+'</span>';if(t.need_label)m+='<span class="pill">'+esc(t.need_label)+' · '+t.need_score+'%</span>';if(t.paused&&t.pause)m+='<span class="pill pause-tag">🌴 Pausada hasta '+esc(fmtDate(t.pause.return_date))+'</span>';if(t.area)m+='<span class="pill">'+esc(t.area.icon||"⌂")+' '+esc(t.area.name)+'</span>';if(t.effective_owner)m+='<span class="pill owner-pill">'+esc(t.effective_owner.icon||"👤")+' Responsable: '+esc(t.effective_owner.name)+'</span>';if((t.supplies||[]).length)m+='<span class="pill">🧴 '+t.supplies.length+' productos</span>';if((t.missing_supplies||[]).length)m+='<span class="pill supply-missing">⛔ Falta: '+esc(t.missing_supplies.map(function(x){return x.name}).join(", "))+'</span>';if(t.attachment_count)m+='<span class="pill">📎 '+t.attachment_count+'</span>';return m}
function taskDoneDefinition(t){return t.definition_of_done?'<div class="done-definition"><strong>Se considera terminada cuando:</strong> '+esc(t.definition_of_done)+'</div>':""}
function card(t,mode){var due=dueText(t);var buttons="";
if(mode==="today")buttons=blockedSupplyAction(t)+'<button class="ghost" onclick="removeToday('+t.id+')">← Quitar de Hoy</button><button class="ghost" onclick="postpone('+t.id+')">Posponer</button><button class="secondary" onclick="completeTask('+t.id+')">✓ Hecha</button>';
if(mode==="upcoming")buttons=blockedSupplyAction(t)+'<button class="secondary" onclick="addToday('+t.id+')">+ Hoy</button><button class="ghost" onclick="editTask('+t.id+')">Editar</button>';
if(mode==="tasks"){buttons=blockedSupplyAction(t)+'<button class="ghost" onclick="editTask('+t.id+')">Editar</button>';if(t.active){if(t.pause&&t.pause.source==="task")buttons+='<button class="secondary" onclick="resumeTask('+t.id+')">Reanudar</button>';else if(!t.paused)buttons+='<button class="ghost" onclick="openPause(\'task\','+t.id+')">🌴 Pausar</button>';buttons+='<button class="ghost" onclick="archiveTask('+t.id+')">Archivar</button>'}buttons+='<button class="danger" onclick="deleteTask('+t.id+')">Eliminar</button>'}
return '<article class="card" style="--c:'+esc(t.color)+'" '+(mode==="today"&&!t.paused?'draggable="true" data-id="'+t.id+'"':'')+'><div class="icon">'+esc(t.icon)+'</div><div><div class="title">'+esc(t.title)+'</div><div class="desc">'+esc(taskDescription(t))+'</div><div class="meta">'+taskMeta(t)+(due?'<span class="pill '+(due.indexOf("pendiente")>0?"overdue":"")+'">'+esc(due)+'</span>':"")+'</div>'+(mode==="tasks"?(needMeter(t)+taskDoneDefinition(t)):"")+'</div><div class="actions">'+buttons+"</div></article>"}
function blockedSupplyAction(t){return t&&t.blocked_by_supplies?'<button class="ghost" onclick="taskSection=\'inventory\';go(\'tasks\')">🛒 Ver compra</button>':""}
function boardCard(t,origin){var due=dueText(t);var buttons=blockedSupplyAction(t);if(t.paused)buttons+='<button class="ghost" onclick="editTask('+t.id+')">Editar</button>';else if(origin==="today")buttons+='<button class="ghost" onclick="removeToday('+t.id+')">← Quitar de Hoy</button><button class="ghost" onclick="postpone('+t.id+')">Posponer</button><button class="secondary" onclick="completeTask('+t.id+')">✓ Hecha</button>';else if(origin==="all")buttons+='<button class="secondary" onclick="addToday('+t.id+')">+ Hoy</button><button class="ghost" onclick="editTask('+t.id+')">Editar</button>';else buttons+='<button class="secondary" onclick="addToday('+t.id+')">+ Hoy</button>';var dragAttr=origin==="all"||t.paused?'':' draggable="true" data-id="'+t.id+'" data-origin="'+origin+'"';return '<article class="card '+(t.blocked_by_supplies?"blocked-supplies":"")+'" style="--c:'+esc(t.color)+'"'+dragAttr+'><div class="icon">'+esc(t.icon)+'</div><div><div class="title">'+esc(t.title)+'</div><div class="desc">'+esc(taskDescription(t))+'</div><div class="meta">'+taskMeta(t)+(due?'<span class="pill '+(due.indexOf("pendiente")>0?"overdue":"")+'">'+esc(due)+'</span>':"")+'</div></div><div class="actions">'+buttons+'</div></article>'}

function activityIcon(kind){if(kind.indexOf("completed")>=0)return"✓";if(kind.indexOf("calendar")>=0||kind.indexOf("event")>=0)return"📅";if(kind.indexOf("inventory")>=0)return"🧴";if(kind.indexOf("attachment")>=0)return"📎";if(kind.indexOf("area")>=0)return"⌂";return"•"}
function activitySeenAt(){try{return localStorage.getItem("casa_activity_seen_at")}catch(e){return null}}
function markActivitySeen(){var newest=(state.activity&&state.activity[0])?state.activity[0].created_at:new Date().toISOString();try{localStorage.setItem("casa_activity_seen_at",newest)}catch(e){}if(view==="board")renderBoard()}
function activityPanel(){var all=state.activity||[];if(!all.length)return"";var seen=activitySeenAt();var cutoff=seen?new Date(seen):new Date(Date.now()-86400000);var items=all.filter(function(x){return new Date(x.created_at)>cutoff}).slice(0,8);if(!items.length)return"";var title=seen?"Desde tu última visita":"Actividad reciente";return'<section class="activity-panel"><div class="activity-head"><div><div class="suggestions-title">📰 '+title+'</div><div class="suggestions-help">Cambios realizados desde este navegador.</div></div><button class="ghost" onclick="markActivitySeen()">Marcar como visto</button></div><div class="activity-list">'+items.map(function(x){return'<div class="activity-item"><span>'+activityIcon(x.kind)+'</span><div><strong>'+esc(x.summary)+'</strong>'+(x.detail?'<div class="muted">'+esc(x.detail)+'</div>':'')+'<div class="activity-time">'+esc(new Date(x.created_at).toLocaleString("es"))+'</div></div></div>'}).join("")+'</div></section>'}
function resumeModeLabel(mode){return mode==="keep_calendar"?"Mantener calendario":"Continuar ciclo"}
function vacationPanel(){var v=state.vacation||{};if(v.active){var names=(v.excluded_area_ids||[]).map(function(id){var a=state.areas.find(function(x){return x.id===id});return a?a.name:null}).filter(Boolean);var excluded=names.length?"Siguen activas: "+names.join(", "):"Todas las áreas de tareas están pausadas";return '<section class="vacation-panel active"><div class="vacation-head"><div><div class="vacation-title">🌴 Modo vacaciones activo</div><div class="vacation-meta">Regreso: <strong>'+esc(fmtDate(v.return_date))+'</strong> · '+esc(resumeModeLabel(v.resume_mode))+'<br>'+esc(excluded)+' · La Agenda y sus avisos siguen activos.</div></div><span class="status">Pausado</span></div><div class="vacation-actions"><button class="secondary" onclick="endVacation()">Terminar vacaciones ahora</button></div></section>'}return '<section class="vacation-panel"><div class="vacation-head"><div><div class="vacation-title">🌴 Modo vacaciones</div><div class="vacation-meta">Pausa temporalmente las tareas sin ocultar reuniones, citas ni vencimientos de la Agenda.</div></div><button class="primary" onclick="openVacation()">Activar</button></div></section>'}
function openVacation(){var choices=state.areas.map(function(a){return '<label class="reminder-option"><input type="checkbox" name="vacation_excluded" value="'+a.id+'"> '+esc(a.icon)+' '+esc(a.name)+'</label>'}).join("");var html='<div class="modalhead"><div><h2>🌴 Modo vacaciones</h2><div class="muted">Las tareas se ocultan de Hoy, Próximamente y Sugeridas. La Agenda continúa funcionando.</div></div><button class="ghost" onclick="closeModal()">×</button></div><form id="vacationform" class="formgrid"><div class="field"><label>Fecha de regreso</label><input name="return_date" type="date" min="'+localDateValue(1)+'" value="'+localDateValue(7)+'" required></div><div class="field"><label>Al volver</label><select name="resume_mode"><option value="continue_cycle">Continuar ciclo · vacaciones no cuentan</option><option value="keep_calendar">Mantener calendario original</option></select></div><div class="field full"><label>Áreas que deben seguir activas</label><div class="reminders">'+(choices||'<span class="muted">No hay áreas activas.</span>')+'</div><div class="muted">Útil para pisos en alquiler, Krankenkassen u otros asuntos que deban seguir visibles.</div></div></form><div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="startVacation()">Activar vacaciones</button></div>';showModal(html)}
async function startVacation(){var f=new FormData(document.getElementById("vacationform"));var o={return_date:String(f.get("return_date")||""),resume_mode:String(f.get("resume_mode")||"continue_cycle"),excluded_area_ids:f.getAll("vacation_excluded").map(Number)};try{await api("/api/vacation/start",{method:"POST",body:JSON.stringify(o)});closeModal();await load()}catch(e){alert(e.message)}}
async function endVacation(){var v=state.vacation||{};var extra=v.resume_mode==="continue_cycle"?" Las fechas se desplazarán solo por los días que habéis estado en vacaciones.":"";if(!confirm("¿Terminar el modo vacaciones ahora?"+extra))return;try{await api("/api/vacation/end",{method:"POST"});await load()}catch(e){alert(e.message)}}
function openPause(kind,id){var item=kind==="task"?state.tasks.find(function(x){return x.id===id}):(state.areas_all||[]).find(function(x){return x.id===id});if(!item)return;var noun=kind==="task"?"tarea":"área";var html='<div class="modalhead"><div><h2>🌴 Pausar '+noun+'</h2><div class="muted">'+esc(item.title||item.name)+'</div></div><button class="ghost" onclick="closeModal()">×</button></div><form id="pauseform" class="formgrid"><div class="field"><label>Reanudar el</label><input name="return_date" type="date" min="'+localDateValue(1)+'" value="'+localDateValue(7)+'" required></div><div class="field"><label>Al reanudar</label><select name="resume_mode"><option value="continue_cycle">Continuar ciclo · pausa no cuenta</option><option value="keep_calendar">Mantener calendario original</option></select></div></form><div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="doPause(\''+kind+'\','+id+')">Pausar</button></div>';showModal(html)}
async function doPause(kind,id){var f=new FormData(document.getElementById("pauseform"));var o={return_date:String(f.get("return_date")||""),resume_mode:String(f.get("resume_mode")||"continue_cycle")};try{await api("/api/"+(kind==="task"?"tasks":"areas")+"/"+id+"/pause",{method:"POST",body:JSON.stringify(o)});closeModal();await load()}catch(e){alert(e.message)}}
async function resumeTask(id){try{await api("/api/tasks/"+id+"/resume",{method:"POST"});await load()}catch(e){alert(e.message)}}
async function resumeArea(id){try{await api("/api/areas/"+id+"/resume",{method:"POST"});await load()}catch(e){alert(e.message)}}
function completedCard(x){var can=!!x.can_undo_to_today;var drag=can?' draggable="true" data-origin="done" data-id="'+x.task_id+'" data-completion-id="'+x.id+'"':'';var action=can?'<button class="ghost" onclick="undoCompletionToToday('+x.id+')">↶ Volver a Hoy</button>':'';return '<div class="done-card"'+drag+'><div class="icon">'+esc(x.icon)+'</div><div><div class="title">'+esc(x.title)+'</div><div class="muted">'+new Date(x.completed_at).toLocaleString("es")+' · '+esc(x.name)+'</div></div><div class="done-actions"><div class="avatar" style="background:'+esc(x.color)+'">'+esc(x.person_icon)+'</div>'+action+'</div></div>'}
async function undoCompletionToToday(completionId){try{var r=await api("/api/completions/"+completionId+"/undo-to-today",{method:"POST"});view="board";await load();showUndo('Realización deshecha · "'+(r.task_title||"Tarea")+'" vuelve a Hoy',null)}catch(e){alert(e.message)}}

function householdOverviewPanel(){
  var shopping=(state.shopping_list||[]).length;
  var blocked=(state.tasks||[]).filter(function(t){return t.active&&t.blocked_by_supplies}).length;
  var spend="—",change="",tickets="—";
  if(homeGastosSummary){
    var cur=homeGastosSummary.current_month||{},pct=homeGastosSummary.change_percent;
    spend=typeof gastosMoney==="function"?gastosMoney(cur.total||0):Number(cur.total||0).toFixed(2)+" €";
    tickets=Number(cur.ticket_count||0);
    if(pct!=null)change=(pct>0?"+":"")+gastosNumber(pct,1)+"% vs. mes anterior";
  }
  return '<section class="activity-panel"><div class="activity-head"><div><div class="suggestions-title">🏠 Resumen del hogar</div><div class="suggestions-help">Tareas, compra e impacto de Gastos en un solo vistazo.</div></div><button class="ghost" onclick="go(\'gastos\')">Abrir Gastos</button></div><div class="stats" style="margin:0">'+
    '<div class="stat"><div class="count">'+shopping+'</div><div>Por comprar</div><div class="muted">productos</div></div>'+
    '<div class="stat"><div class="count">'+blocked+'</div><div>Bloqueadas</div><div class="muted">tareas por material</div></div>'+
    '<div class="stat"><div class="count">'+esc(spend)+'</div><div>Gasto del mes</div><div class="muted">'+esc(change||"sin comparación")+'</div></div>'+
    '<div class="stat"><div class="count">'+esc(tickets)+'</div><div>Tickets</div><div class="muted">este mes</div></div>'+
  '</div>'+(homeGastosError?'<div class="settings-warning" style="margin-top:10px">No se pudo cargar el resumen de Gastos: '+esc(homeGastosError)+'</div>':"")+'</section>';
}
async function loadHomeGastosSummary(){
  if(homeGastosLoading||homeGastosLoaded)return;
  homeGastosLoading=true;homeGastosError="";
  try{homeGastosSummary=await api("/api/gastos/home-summary")}catch(e){homeGastosError=e.message||String(e)}
  homeGastosLoading=false;homeGastosLoaded=true;
  if(view==="board")renderBoard();
}

function renderBoard(){var recent=state.history.slice(0,8);var all=state.tasks.filter(function(t){return t.active});var upcomingEvents=state.event_upcoming||[];var todayEvents=state.event_today||[];var h='<div class="pagehead"><div><h1>Tablero</h1><div class="subtitle">Tareas y agenda doméstica en un mismo vistazo.</div></div><button class="primary" onclick="openTask()">+ Nueva tarea</button></div>'+householdOverviewPanel()+activityPanel()+vacationPanel()+suggestionsPanel()+'<div class="mobile-board-nav"><button aria-label="Columna anterior" onclick="moveBoard(-1)">←</button><div class="mobile-board-meta"><strong id="mobileBoardLabel">Hoy</strong><span id="mobileBoardPos">3 / 4</span></div><button aria-label="Columna siguiente" onclick="moveBoard(1)">→</button></div><div class="kanban" id="kanbanBoard">';
h+='<section class="kanban-col" id="col-all" data-drop="all"><div class="kanban-head"><div><div class="kanban-title">Todas las tareas</div><div class="drag-hint">Catálogo activo · usa + Hoy para añadir</div></div><span class="kanban-count">'+all.length+'</span></div><div class="kanban-list">'+(all.length?all.map(function(t){return boardCard(t,"all")}).join(""):'<div class="kanban-empty">No hay tareas activas.</div>')+'</div></section>';
h+='<section class="kanban-col" id="col-upcoming" data-drop="upcoming"><div class="kanban-head"><div><div class="kanban-title">Próximamente</div><div class="drag-hint">Arrastra aquí desde Hoy para corregir una selección</div></div><span class="kanban-count">'+(state.upcoming.length+upcomingEvents.length)+'</span></div><div class="kanban-list">'+upcomingEvents.map(function(e){return eventCard(e,true)}).join("")+(state.upcoming.length?state.upcoming.map(function(t){return boardCard(t,"upcoming")}).join(""):(upcomingEvents.length?"":'<div class="kanban-empty">No hay nada próximo.</div>'))+'</div></section>';
h+='<section class="kanban-col" id="col-today" data-drop="today"><div class="kanban-head"><div><div class="kanban-title">Hoy</div><div class="drag-hint">Arrastra a Próximamente para quitar de Hoy</div></div><span class="kanban-count">'+(state.today.length+todayEvents.length)+'</span></div><div class="kanban-list">'+todayEvents.map(function(e){return eventCard(e,true)}).join("")+(state.today.length?state.today.map(function(t){return boardCard(t,"today")}).join(""):(todayEvents.length?"":'<div class="kanban-empty">🎉 Nada pendiente para hoy.</div>'))+'</div></section>';
h+='<section class="kanban-col" id="col-done" data-drop="done"><div class="kanban-head"><div><div class="kanban-title">Realizadas</div><div class="drag-hint">Arrastra una realización reversible a Hoy para corregirla</div></div><span class="kanban-count">'+recent.length+'</span></div><div class="kanban-list">'+(recent.length?recent.map(completedCard).join(""):'<div class="kanban-empty">Aún no hay tareas realizadas.</div>')+'</div></section></div>';
document.getElementById("main").innerHTML=h;bindBoardDrag();initMobileBoard();loadHomeGastosSummary();if((state.shopping_list||[]).length)loadShoppingPlan(false)}

function renderToday(){var h='<div class="pagehead"><div><h1>Hoy</h1><div class="subtitle">Una cola pequeña para lo que toca ahora.</div></div><button class="primary" onclick="openTask()">+ Añadir</button></div>';
h+=state.today.length?'<div class="grid">'+state.today.map(function(t){return card(t,"today")}).join("")+"</div>":'<div class="empty">🎉 No hay tareas en la cola de hoy.</div>';
h+='<div class="drop" id="done">Arrastra aquí una tarea terminada<br><span class="muted">o usa el botón ✓ Hecha</span></div>';document.getElementById("main").innerHTML=h;bindDrag()}
function renderUpcoming(){var h='<div class="pagehead"><div><h1>Próximamente</h1><div class="subtitle">Lo que viene después, ordenado por fecha.</div></div></div>';if(!state.upcoming.length)h+='<div class="empty">No hay tareas futuras.</div>';else{var groups={};state.upcoming.forEach(function(t){var k=t.next_due||"Sin fecha";(groups[k]||(groups[k]=[])).push(t)});Object.keys(groups).forEach(function(k){h+='<div class="section">'+fmtDate(k)+'</div><div class="grid">'+groups[k].map(function(t){return card(t,"upcoming")}).join("")+"</div>"})}document.getElementById("main").innerHTML=h}
function taskSectionSwitcher(){return'<div class="task-switcher"><button class="ghost '+(taskSection==="tasks"?"active":"")+'" onclick="switchTaskSection(\'tasks\')">☰ Tareas</button><button class="ghost '+(taskSection==="inventory"?"active":"")+'" onclick="switchTaskSection(\'inventory\')">🧺 Inventario y Comprar'+((state.shopping_list||[]).length?' · '+state.shopping_list.length:'')+'</button></div>'}
function switchTaskSection(section){taskSection=section;renderTasks()}
function stockLabel(status){return status==="out"?"Falta":status==="low"?"Poco":"Hay"}
function shoppingPlanItem(itemId){return shoppingPlan&&shoppingPlan.items?(shoppingPlan.items.find(function(x){return Number(x.id)===Number(itemId)})||null):null}
function shoppingRecommendationMeta(item){
  var p=shoppingPlanItem(item.id);if(!p)return"";
  var rec=p.recommended_supermarket,last=p.last_purchase;
  var bits=[];
  if(rec&&rec.supermarket)bits.push("💡 "+rec.supermarket+(rec.average_unit_price!=null?" · "+(typeof gastosMoney==="function"?gastosMoney(rec.average_unit_price):Number(rec.average_unit_price).toFixed(2)+" €")+"/u":""));
  if(last&&last.supermarket)bits.push("Última: "+last.supermarket+(last.unit_price!=null?" · "+(typeof gastosMoney==="function"?gastosMoney(last.unit_price):Number(last.unit_price).toFixed(2)+" €")+"/u":""));
  return bits.length?'<div class="shopping-required">'+bits.map(function(x){return esc(x)}).join(" · ")+'</div>':"";
}
function shoppingPlanPanel(){
  if(!(state.shopping_list||[]).length)return"";
  if(!shoppingPlanLoaded)return'<section class="inventory-panel"><div class="section">🧭 Plan de compra</div><div class="empty">'+(shoppingPlanLoading?"Calculando supermercados…":"Cargando recomendaciones…")+'</div></section>';
  if(!shoppingPlan||!(shoppingPlan.groups||[]).length)return"";
  return '<section class="inventory-panel"><div class="section">🧭 Plan de compra por supermercado</div><div class="inventory-list">'+shoppingPlan.groups.map(function(g){
    var est=typeof gastosMoney==="function"?gastosMoney(g.estimated_unit_total):Number(g.estimated_unit_total).toFixed(2)+" €";
    return '<div class="shopping-card"><div><strong>'+esc(g.supermarket)+'</strong><span class="pill">'+g.count+' producto'+(g.count===1?"":"s")+'</span>'+(g.priced_count?'<span class="pill">≈ '+esc(est)+' base/u.</span>':"")+'</div><div class="shopping-required">'+g.items.map(function(x){return esc(x.name)+(x.purchase_quantity?' · '+esc(x.purchase_quantity):"")}).join("<br>")+'</div></div>';
  }).join("")+'</div></section>';
}
async function loadShoppingPlan(force){
  if(shoppingPlanLoading||(!force&&shoppingPlanLoaded))return;
  shoppingPlanLoading=true;
  try{shoppingPlan=await api("/api/gastos/shopping-plan")}catch(e){shoppingPlan={items:[],groups:[],error:e.message||String(e)}}
  shoppingPlanLoaded=true;shoppingPlanLoading=false;
  if(view==="tasks"&&taskSection==="inventory")renderInventory();
  if(view==="board")renderBoard();
  if(view==="gastos"&&typeof renderGastosContent==="function")renderGastosContent();
}
function taskDescription(t){
  if(t&&t.is_shopping_task&&shoppingPlan&&shoppingPlan.groups&&shoppingPlan.groups.length){
    return shoppingPlan.groups.map(function(g){return g.supermarket+": "+g.items.map(function(x){return x.name}).join(", ")}).join(" · ");
  }
  return t.description||"";
}
function shoppingCard(item){var required=(item.required_by||[]).map(function(t){return t.title}).join(", ");return'<div class="shopping-card"><div><strong>'+esc(item.name)+'</strong>'+(item.purchase_quantity?'<span class="pill">Comprar: '+esc(item.purchase_quantity)+'</span>':'')+'<span class="pill">'+esc(item.category)+'</span></div>'+(required?'<div class="shopping-required">Necesario para: '+esc(required)+'</div>':'<div class="shopping-required">Añadido manualmente a Comprar.</div>')+shoppingRecommendationMeta(item)+'<div class="actions"><button class="secondary" onclick="setInventoryStock('+item.id+',\'ok\',false)">✓ Repuesto</button><button class="ghost" onclick="openInventoryItem('+item.id+')">Editar</button></div></div>'}
function inventoryItemCard(item){var cls=item.stock_status==="out"?"out":item.stock_status==="low"?"low":"";var area=item.area?'<span class="pill">'+esc(item.area.icon||"⌂")+' '+esc(item.area.name)+'</span>':"";var linked=(item.required_by||[]).length?'<span class="pill">'+item.required_by.length+' tareas</span>':"";var gastos=item.gastos_linked?'<span class="pill">🛒 Gastos vinculado</span>':"";var purchased=item.last_purchased_at?'<span class="pill">✓ Comprado '+esc(fmtDate(item.last_purchased_at))+'</span>':"";var manual=item.stock_status==="ok"?(item.shopping_requested?'<button class="ghost" onclick="setInventoryStock('+item.id+',\'ok\',false)">Quitar de Comprar</button>':'<button class="ghost" onclick="setInventoryStock('+item.id+',\'ok\',true)">+ Comprar</button>'):"";return'<div class="inventory-item '+cls+'"><div><strong>'+esc(item.name)+'</strong><div class="muted">'+esc(item.notes||"")+'</div><div class="meta"><span class="pill">'+esc(item.category)+'</span>'+area+linked+gastos+purchased+(item.purchase_quantity?'<span class="pill">🛒 '+esc(item.purchase_quantity)+'</span>':'')+'</div></div><div><div class="stock-buttons"><button class="'+(item.stock_status==="ok"?"secondary":"ghost")+'" onclick="setInventoryStock('+item.id+',\'ok\',false)">Hay</button><button class="'+(item.stock_status==="low"?"secondary":"ghost")+'" onclick="setInventoryStock('+item.id+',\'low\',null)">Poco</button><button class="'+(item.stock_status==="out"?"secondary":"ghost")+'" onclick="setInventoryStock('+item.id+',\'out\',null)">Falta</button></div><div class="actions">'+manual+'<button class="ghost" onclick="openInventoryItem('+item.id+')">Editar</button><button class="ghost" onclick="archiveInventoryItem('+item.id+')">Archivar</button></div></div></div>'}
function renderInventory(){var shopping=state.shopping_list||[];var active=state.inventory||[];var archived=(state.inventory_all||[]).filter(function(x){return !x.active});var h='<div class="pagehead"><div><h1>Tareas</h1><div class="subtitle">Productos necesarios para hacer las tareas y una lista de compra agregada.</div></div><button class="primary" onclick="openInventoryItem()">+ Nuevo producto</button></div>'+taskSectionSwitcher()+'<div class="inventory-grid"><section class="inventory-panel"><div class="section">🛒 Comprar · '+shopping.length+'</div><div class="inventory-list">'+(shopping.length?shopping.map(shoppingCard).join(""):'<div class="empty">No falta ningún producto.</div>')+'</div></section>'+shoppingPlanPanel()+'<section class="inventory-panel"><div class="section">Inventario · '+active.length+'</div><div class="inventory-list">'+(active.length?active.map(inventoryItemCard).join(""):'<div class="empty">Todavía no hay productos.</div>')+'</div>'+(archived.length?'<div class="section">Archivados · '+archived.length+'</div><div class="inventory-list">'+archived.map(function(item){return'<div class="inventory-item"><div><strong>'+esc(item.name)+'</strong></div><button class="secondary" onclick="restoreInventoryItem('+item.id+')">Restaurar</button></div>'}).join("")+'</div>':'')+'</section></div>';document.getElementById("main").innerHTML=h;if(shopping.length)loadShoppingPlan(false)}
function renderTasks(){if(taskSection==="inventory"){renderInventory();return}var active=state.tasks.filter(function(t){return t.active});var archived=state.tasks.filter(function(t){return !t.active});var h='<div class="pagehead"><div><h1>Tareas</h1><div class="subtitle">Catálogo maestro de tareas domésticas.</div></div><button class="primary" onclick="openTask()">+ Nueva tarea</button></div>'+taskSectionSwitcher()+'<div class="toolbar"><input class="search" id="q" placeholder="Buscar..." oninput="filterTasks()"></div><div id="tasklist">';
h+='<div class="section">Activas · '+active.length+'</div><div class="grid">'+active.map(function(t){return card(t,"tasks")}).join("")+"</div>";if(archived.length)h+='<div class="section">Archivadas · '+archived.length+'</div><div class="grid">'+archived.map(function(t){return card(t,"tasks")}).join("")+"</div>";h+="</div>";document.getElementById("main").innerHTML=h}

function filterTasks(){var q=document.getElementById("q").value.toLowerCase();document.querySelectorAll("#tasklist .card").forEach(function(el){el.style.display=el.innerText.toLowerCase().indexOf(q)>=0?"":"none"})}
function openInventoryItem(id){var item=id?(state.inventory_all||[]).find(function(x){return x.id===id}):null;var html='<div class="modalhead"><div><h2>'+(item?"Editar producto":"Nuevo producto")+'</h2><div class="muted">Usa Hay / Poco / Falta. Si lo vinculas con Gastos, una compra registrada puede marcarlo automáticamente como repuesto.</div></div><button class="ghost" onclick="closeModal()">×</button></div><form id="inventoryform" class="formgrid"><div class="field full"><label>Producto</label><input name="name" required maxlength="120" value="'+esc(item?item.name:"")+'" placeholder="Ej. Limpiador de baño"></div><div class="field"><label>Categoría</label><input name="category" value="'+esc(item?item.category:"Limpieza")+'"></div><div class="field"><label>Área</label><select name="area_id">'+activeAreaOptions(item&&item.area_id?item.area_id:null)+'</select></div><div class="field"><label>Unidad</label><input name="unit" value="'+esc(item?item.unit:"")+'" placeholder="Ej. botella, paquete"></div><div class="field"><label>Qué comprar</label><input name="purchase_quantity" value="'+esc(item?item.purchase_quantity:"")+'" placeholder="Ej. 1 botella"></div><div class="field"><label>Estado</label><select name="stock_status"><option value="ok">Hay</option><option value="low">Poco</option><option value="out">Falta</option></select></div><div class="field full"><label>Producto correspondiente en Gastos</label><select name="gastos_product_id" id="inventoryGastosProduct"><option value="">Sin vincular</option><option value="" disabled>Cargando catálogo de Gastos…</option></select><div class="muted">Al registrar un ticket con este producto se marcará como Hay y saldrá de Comprar.</div></div><div class="field full"><label>Notas</label><textarea name="notes">'+esc(item?item.notes:"")+'</textarea></div></form><div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveInventoryItem('+(item?item.id:"null")+')">Guardar</button></div>';showModal(html);document.querySelector('#inventoryform [name="stock_status"]').value=item?item.stock_status:"ok";loadInventoryGastosProducts(item&&item.gastos_product_id?item.gastos_product_id:null,item?item.name:"")}
async function loadInventoryGastosProducts(selectedId,itemName){var select=document.getElementById("inventoryGastosProduct");if(!select)return;if(!gastosIntegrationReady||!gastosIntegrationReady()){select.innerHTML='<option value="">Gastos no configurado</option>';return}try{var r=await api("/api/gastos/products?limit=500");var products=r.items||[];products.sort(function(a,b){return String(a.name).localeCompare(String(b.name),"es",{sensitivity:"base"})});var selected=selectedId==null?"":String(selectedId);var exact=null;if(!selected&&itemName){exact=products.find(function(p){return String(p.name||"").localeCompare(String(itemName||""),"es",{sensitivity:"base"})===0})}select.innerHTML='<option value="">Sin vincular</option>'+products.map(function(p){var isSelected=String(p.id)===selected||(!selected&&exact&&p.id===exact.id);return'<option value="'+p.id+'" '+(isSelected?"selected":"")+'>'+esc(p.name)+(p.purchase_count?' · '+p.purchase_count+' compras':'')+'</option>'}).join("")}catch(e){select.innerHTML='<option value="">No se pudo cargar Gastos</option>';select.title=e.message}}
async function saveInventoryItem(id){var f=new FormData(document.getElementById("inventoryform"));var o=Object.fromEntries(f.entries());o.area_id=o.area_id?Number(o.area_id):null;o.gastos_product_id=o.gastos_product_id?Number(o.gastos_product_id):null;o.shopping_requested=id?Boolean((state.inventory_all||[]).find(function(x){return x.id===id})?.shopping_requested):false;try{await api(id?"/api/inventory/"+id:"/api/inventory",{method:id?"PUT":"POST",body:JSON.stringify(o)});closeModal();shoppingPlanLoaded=false;shoppingPlan=null;await load();taskSection="inventory";renderTasks()}catch(e){alert(e.message)}}
async function setInventoryStock(id,status,requested){var body={stock_status:status,shopping_requested:requested};try{await api("/api/inventory/"+id+"/stock",{method:"POST",body:JSON.stringify(body)});shoppingPlanLoaded=false;shoppingPlan=null;await load();taskSection="inventory";renderTasks()}catch(e){alert(e.message)}}
async function archiveInventoryItem(id){if(!confirm("¿Archivar este producto?"))return;try{await api("/api/inventory/"+id,{method:"DELETE"});shoppingPlanLoaded=false;shoppingPlan=null;await load();taskSection="inventory";renderTasks()}catch(e){alert(e.message)}}
async function restoreInventoryItem(id){try{await api("/api/inventory/"+id+"/restore",{method:"POST"});shoppingPlanLoaded=false;shoppingPlan=null;await load();taskSection="inventory";renderTasks()}catch(e){alert(e.message)}}

function telegramPanel(){var t=state.telegram||{};var h='<div class="telegram-panel"><div class="telegram-head"><div><div class="telegram-title">✈️ Telegram</div><div class="telegram-help">Avisos y control rápido de Casa Tareas desde el grupo.</div></div>';
if(!t.token_configured){h+='<span class="telegram-status warn">Falta token</span></div><div class="telegram-help">Crea el bot con @BotFather y guarda el token desde <strong>⚙ Configuración → Telegram</strong>. No hace falta reiniciar Docker.</div><div class="telegram-actions"><button class="primary" onclick="go(\'settings\')">Configurar Telegram</button></div></div>';return h}
if(t.chat_id){var bot=t.bot_username?' · @'+esc(t.bot_username):'';h+='<span class="telegram-status ok">● Conectado</span></div><div><strong>'+esc(t.chat_title||String(t.chat_id))+'</strong><div class="telegram-help">Bot'+bot+'. Solo este chat puede modificar Casa Tareas. Los recordatorios se revisan aproximadamente cada '+esc(t.poll_seconds||60)+' segundos.</div></div><div class="telegram-commands"><div><code>/hoy</code> — ver tareas y eventos de hoy</div><div><code>/comprar</code> — ver la lista de compra</div><div><code>/stock Limpiador baño | falta</code></div><div><code>/tarea Revisar contrato | Piso Fanalwegle | gestión</code></div><div><code>/hecha Sacar basura</code> — pregunta quién la hizo</div><div><code>/mover Revisar seguro | Krankenkassen</code></div><div><code>/posponer Limpiar baño | mañana</code></div><div><code>/evento Reunión | 2026-11-12 19:00 | Piso Im Gapetsch | 1d,2h</code></div><div><code>/deshacer</code> — deshacer el último cambio hecho desde Telegram</div><div class="telegram-help">También puedes usar <code>/casa hecha …</code>, <code>/casa añade …</code>, etc. No hay comandos de borrado.</div></div><div class="telegram-actions"><button class="secondary" onclick="testTelegram()">Enviar prueba</button><button class="ghost" onclick="detectTelegramChats()">Cambiar chat</button><button class="danger" onclick="disconnectTelegram()">Desconectar</button></div></div>';return h}
h+='<span class="telegram-status warn">Sin chat</span></div><div class="telegram-help">Añade el bot al grupo y envía allí <strong>/casa</strong>. El bot registra chats en segundo plano; espera unos segundos y pulsa Detectar chats.</div><div class="telegram-actions"><button class="primary" onclick="detectTelegramChats()">Detectar chats</button></div></div>';return h}

function calendarPanel(){var list=state.calendar_subscriptions||[];var h='<section class="calendar-panel"><div class="telegram-head"><div><div class="telegram-title">🗓️ Calendarios externos</div><div class="telegram-help">Suscripciones iCal de solo lectura. La URL completa no se muestra porque puede contener un token privado.</div></div><button class="primary" onclick="openCalendarSubscription()">+ Añadir</button></div>';if(!list.length)return h+'<div class="muted">No hay calendarios externos conectados.</div></section>';h+=list.map(function(cal){var status=cal.last_error?'<div class="calendar-error">⚠ '+esc(cal.last_error)+'</div>':'<div class="muted">'+(cal.last_sync_at?'Sincronizado '+esc(new Date(cal.last_sync_at).toLocaleString("es")):'Todavía sin sincronizar')+'</div>';var area=cal.area?' · '+esc(cal.area.icon||"⌂")+' '+esc(cal.area.name):'';return'<div class="calendar-source"><div><strong>'+esc(cal.name)+'</strong><div class="muted">'+esc(cal.url_display||"") + area+'</div>'+status+'</div><div class="actions"><button class="ghost" onclick="syncCalendar('+cal.id+')">Sincronizar</button><button class="danger" onclick="deleteCalendar('+cal.id+')">Eliminar</button></div></div>'}).join("");return h+'<div class="telegram-actions"><button class="ghost" onclick="syncAllCalendars()">Sincronizar todos</button></div></section>'}
function openCalendarSubscription(){var html='<div class="modalhead"><div><h2>Calendario externo</h2><div class="muted">Pega una URL iCal/ICS HTTPS. Puede ser un calendario escolar, deportivo, de comunidad, etc.</div></div><button class="ghost" onclick="closeModal()">×</button></div><form id="calendarform" class="formgrid"><div class="field full"><label>Nombre</label><input name="name" required maxlength="120" placeholder="Ej. Colegio" ></div><div class="field full"><label>URL iCal / ICS</label><input name="url" type="url" required placeholder="https://…/calendar.ics"></div><div class="field full"><label>Área opcional</label><select name="area_id">'+activeAreaOptions(null)+'</select></div></form><div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveCalendarSubscription()">Conectar</button></div>';showModal(html)}
async function saveCalendarSubscription(){var f=new FormData(document.getElementById("calendarform"));var o=Object.fromEntries(f.entries());o.area_id=o.area_id?Number(o.area_id):null;try{var r=await api("/api/calendars",{method:"POST",body:JSON.stringify(o)});closeModal();await load();if(!r.synced&&r.error)alert("El calendario se guardó, pero no pudo sincronizarse todavía: "+r.error)}catch(e){alert(e.message)}}
async function syncCalendar(id){try{await api("/api/calendars/"+id+"/sync",{method:"POST"});await load()}catch(e){alert(e.message)}}
async function syncAllCalendars(){try{await api("/api/calendars/sync",{method:"POST"});await load()}catch(e){alert(e.message)}}
async function deleteCalendar(id){var cal=(state.calendar_subscriptions||[]).find(function(x){return x.id===id});if(!confirm('¿Eliminar la suscripción "'+(cal?cal.name:"")+'"? Los eventos importados desaparecerán de Casa Tareas, pero no se modifica el calendario original.'))return;try{await api("/api/calendars/"+id,{method:"DELETE"});await load()}catch(e){alert(e.message)}}
function renderEvents(){var now=new Date();var all=state.agenda_events||state.events||[];var future=all.filter(function(e){return new Date(e.event_at)>=now||e.all_day&&new Date(e.event_at).toDateString()===now.toDateString()});var past=all.filter(function(e){return future.indexOf(e)<0}).reverse();var h='<div class="pagehead"><div><h1>Agenda</h1><div class="subtitle">Eventos propios y calendarios externos en un mismo lugar.</div></div></div>'+telegramPanel()+calendarPanel()+'<div class="event-toolbar"><button class="primary" onclick="openEvent()">+ Nuevo evento</button><button class="ghost" onclick="requestBrowserNotifications()">🔔 Avisos del navegador</button></div>';
h+='<div class="section">Próximos · '+future.length+'</div><div class="event-list">'+(future.length?future.map(function(e){return eventCard(e,false)}).join(""):'<div class="empty">No hay eventos próximos.</div>')+'</div>';
if(past.length)h+='<div class="section">Pasados · '+past.length+'</div><div class="event-list">'+past.slice(0,30).map(function(e){return eventCard(e,false)}).join("")+'</div>';
document.getElementById("main").innerHTML=h}

function areaTaskCard(t){var draggable=t.active&&!t.paused;var meta=(t.active?"Activa":"Archivada")+' · '+(t.task_type==="management"?"🧠 Gestión":"🧹 Ejecución")+(t.paused&&t.pause?' · 🌴 hasta '+fmtDate(t.pause.return_date):'');var actions=(draggable?'<button class="ghost" onclick="openMoveTaskArea('+t.id+')">Mover</button>':'')+'<button class="ghost" onclick="editTask('+t.id+')">Editar</button>';return '<div class="area-task '+(t.active?"":"archived")+'" draggable="'+(draggable?"true":"false")+'" data-area-task-id="'+t.id+'" data-current-area="'+(t.area_id==null?"":t.area_id)+'"><div class="icon">'+esc(t.icon)+'</div><div><div class="area-task-title">'+esc(t.title)+'</div><div class="area-task-meta">'+esc(meta)+'</div></div><div class="actions">'+actions+'</div></div>'}
