function renderAreas(){var all=state.areas_all&&state.areas_all.length?state.areas_all:state.areas;var h='<div class="pagehead"><div><h1>Áreas</h1><div class="subtitle">Organiza responsabilidades, mueve tareas y pausa temporalmente ámbitos completos.</div></div><button class="primary" onclick="openArea()">+ Nueva área</button></div><div class="areas-admin">';
h+='<div class="area-row area-drop area-unassigned" data-area-id="" data-area-active="'+((state.vacation&&state.vacation.active)?"0":"1")+'"><div class="icon">📥</div><div><div class="person-name">Sin área</div><div class="desc">Tareas todavía no asignadas a un ámbito de responsabilidad.</div><div class="meta"><span class="pill">'+state.tasks.filter(function(t){return t.area_id==null}).length+' tareas</span>'+((state.vacation&&state.vacation.active)?'<span class="pill pause-tag">🌴 Vacaciones</span>':'')+'</div></div><div></div><div class="area-tasks">'+areaTaskList(null)+'</div></div>';
if(!all.length)h+='<div class="empty">No hay áreas configuradas.</div>';else h+=all.map(function(a){var owner=a.owner?(a.owner.active?'<div class="area-owner"><span class="mini-avatar" style="background:'+esc(a.owner.color)+'">'+esc(a.owner.icon)+'</span>Responsable: <strong>'+esc(a.owner.name)+'</strong></div>':'<div class="area-owner">⚠ Responsable inactivo: <strong>'+esc(a.owner.name)+'</strong></div>'):'<div class="area-owner">Sin responsable asignado</div>';var archivedCount=Math.max(0,(a.total_task_count||0)-(a.task_count||0));var countText=(a.total_task_count||0)+' tareas'+(archivedCount?' · '+archivedCount+' archivadas':'');var eventText=(a.event_count||0)+' eventos';var docText=(a.attachment_count||0)+' documentos';var pauseText=a.paused&&a.pause?'<span class="pill pause-tag">🌴 '+(a.pause.source==="vacation"?"Vacaciones":"Pausada")+' hasta '+esc(fmtDate(a.pause.return_date))+'</span>':'';var deleteDisabled=(a.total_task_count||0)>0||(a.event_count||0)>0;var actions='<button class="ghost" onclick="openArea('+a.id+')">Editar</button>';if(a.active){if(a.pause&&a.pause.source==="area")actions+='<button class="secondary" onclick="resumeArea('+a.id+')">Reanudar</button>';else if(!a.paused)actions+='<button class="ghost" onclick="openPause(\'area\','+a.id+')">🌴 Pausar</button>';actions+='<button class="ghost" onclick="archiveArea('+a.id+')">Archivar</button>'}else actions+='<button class="secondary" onclick="restoreArea('+a.id+')">Restaurar</button>';actions+='<button class="danger" '+(deleteDisabled?'disabled title="Mueve primero todas las tareas y eventos a otra área"':'onclick="deleteAreaPermanently('+a.id+')"')+'>Eliminar</button>';return '<div class="area-row area-drop '+(a.active?"":"inactive")+'" data-area-id="'+a.id+'" data-area-active="'+(a.active&&!a.paused?1:0)+'" style="--c:'+esc(a.color)+'"><div class="icon">'+esc(a.icon)+'</div><div><div class="person-name">'+esc(a.name)+'</div><div class="desc">'+esc(a.description)+'</div>'+owner+'<div class="meta"><span class="pill">'+countText+'</span><span class="pill">'+eventText+'</span><span class="pill">📎 '+docText+'</span>'+pauseText+'<span class="status '+(a.active?"":"off")+'">'+(a.active?"Activa":"Archivada")+'</span></div></div><div class="actions">'+actions+'</div><div class="area-tasks">'+areaTaskList(a.id)+'</div></div>'}).join("");
h+='</div>';document.getElementById("main").innerHTML=h;bindAreaDrag()}

function renderPeople(){var all=state.people_all&&state.people_all.length?state.people_all:state.people;var h='<div class="pagehead"><div><h1>Personas</h1><div class="subtitle">Gestiona quién puede figurar como autor de una tarea.</div></div><button class="primary" onclick="openPerson()">+ Nueva persona</button></div><div class="people-admin">';if(!all.length)h+='<div class="empty">No hay personas configuradas.</div>';else h+=all.map(function(p){return '<div class="person-row '+(p.active?"":"inactive")+'"><div class="avatar" style="background:'+esc(p.color)+'">'+esc(p.icon)+'</div><div><div class="person-name">'+esc(p.name)+'</div><span class="status '+(p.active?"":"off")+'">'+(p.active?"Activa":"Eliminada")+'</span></div><div class="actions"><button class="ghost" onclick="openPerson('+p.id+')">Editar</button>'+(p.active?'<button class="danger" onclick="deletePerson('+p.id+')">Eliminar</button>':'<button class="secondary" onclick="restorePerson('+p.id+')">Restaurar</button>')+'</div></div>'}).join("");h+='</div>';document.getElementById("main").innerHTML=h}
function telegramSourceLabel(source){if(source==="environment")return"Gestionado por .env / entorno";if(source==="application")return"Guardado en Casa Tareas";return"No configurado"}
