function renderSettings(){var s=state.settings||{};var r=s.runtime||{};var t=s.telegram||state.telegram||{};var cal=s.calendars||{};var att=s.attachments||{};var integrations=s.integrations||{};var gastos=integrations.gastos_comida||{};var configured=!!t.token_configured;var source=telegramSourceLabel(t.token_source);var bot=t.bot_username?"@"+t.bot_username:"—";var group=t.chat_id?(t.chat_title||String(t.chat_id)):"Sin grupo seleccionado";var tokenControls="";
if(t.token_editable){tokenControls='<div class="secret-input"><input id="telegramTokenSetting" type="password" autocomplete="new-password" placeholder="'+(configured?"Pega un token nuevo para sustituir el actual":"Pega aquí el token de BotFather")+'"><button class="primary" onclick="saveTelegramTokenSetting()">'+(configured?"Sustituir":"Guardar y validar")+'</button></div>'+(configured?'<div class="settings-actions"><button class="danger" onclick="deleteTelegramTokenSetting()">Eliminar token guardado</button></div>':'')}else{tokenControls='<div class="settings-warning">Este token viene de <code>TELEGRAM_BOT_TOKEN</code>. Para administrarlo desde esta pantalla, elimina esa variable de <code>.env</code> y recrea el contenedor una única vez.</div>'}
var telegramActions=configured?'<div class="settings-actions">'+(t.chat_id?'<button class="secondary" onclick="testTelegram()">Enviar prueba</button><button class="ghost" onclick="detectTelegramChats()">Cambiar grupo</button><button class="ghost" onclick="disconnectTelegram()">Desconectar grupo</button>':'<button class="primary" onclick="detectTelegramChats()">Detectar grupos</button>')+'</div>':'';
var h='<div class="pagehead"><div><h1>Configuración</h1><div class="subtitle">Ajustes de Casa Tareas sin editar archivos del servidor.</div></div></div><div class="settings-grid">';
h+='<section class="settings-card wide"><div class="settings-status"><div><h2>✈️ Telegram</h2><div class="muted">El token nunca vuelve a mostrarse después de guardarlo.</div></div><span class="telegram-status '+(configured?"ok":"warn")+'">'+(configured?"● Configurado":"Sin configurar")+'</span></div><div class="settings-kv"><div>Origen del token</div><div>'+esc(source)+'</div><div>Bot</div><div>'+esc(bot)+'</div><div>Grupo</div><div>'+esc(group)+'</div><div>Worker</div><div>'+(t.worker_running?"Activo":"Detenido")+'</div><div>Último contacto</div><div>'+esc(formatLastContact(t.last_contact_at))+'</div></div>'+tokenControls+telegramActions+'<div class="settings-note">Para conectarlo a un grupo: añade el bot al grupo, escribe <code>/casa</code>, espera unos segundos y pulsa <strong>Detectar grupos</strong>. Si el token se guarda aquí queda dentro de <code>data/chores.db</code>; trata las copias de seguridad de <code>data/</code> como información sensible.</div></section>';
h+='<section class="settings-card wide"><h2>⚙️ Funcionamiento</h2><form id="runtimeSettingsForm" class="runtime-form"><div class="field"><label>Zona horaria</label><input name="timezone" value="'+esc(r.timezone||"Europe/Zurich")+'" placeholder="Europe/Zurich"></div><div class="field"><label>Revisar recordatorios Telegram cada</label><input name="telegram_poll_seconds" type="number" min="30" max="3600" value="'+esc(r.telegram_poll_seconds||60)+'"><span class="muted">segundos</span></div><div class="field"><label>Sincronizar calendarios cada</label><input name="ical_sync_minutes" type="number" min="5" max="1440" value="'+esc(r.ical_sync_minutes||30)+'"><span class="muted">minutos</span></div><div class="field"><label>Máximo por adjunto</label><input name="max_attachment_mb" type="number" min="1" max="500" value="'+esc(r.max_attachment_mb||20)+'"><span class="muted">MB</span></div></form><div class="settings-actions"><button class="primary" onclick="saveRuntimeSettings()">Guardar ajustes</button></div><div class="settings-note">Estos cambios se aplican en caliente. El puerto HTTP sigue siendo una opción de Docker y no se cambia desde la aplicación.</div></section>';
h+='<section class="settings-card wide"><div class="settings-status"><div><h2>🛒 Gastos de comida</h2><div class="muted">Conecta Casa Tareas con el histórico de compras mediante la API interna.</div></div><span class="telegram-status '+(gastos.configured?"ok":"warn")+'">'+(gastos.configured?"● Configurado":"Sin configurar")+'</span></div><form id="gastosIntegrationForm" class="runtime-form"><div class="field full"><label>URL del servicio</label><input name="url" value="'+esc(gastos.url||"")+'" placeholder="http://gastos-comida:8000"></div></form><div class="settings-actions"><button class="primary" onclick="saveGastosIntegration()">Guardar</button>'+(gastos.configured?'<button class="secondary" onclick="testGastosIntegration()">Probar conexión</button><button class="ghost" onclick="clearGastosIntegration()">Desconectar</button>':'')+'</div><div class="settings-kv">'+(gastos.last_ok_at?'<div>Última prueba correcta</div><div>'+esc(formatLastContact(gastos.last_ok_at))+'</div>':'')+(gastos.last_error?'<div>Último error</div><div>'+esc(gastos.last_error)+'</div>':'')+'</div><div class="settings-note">En el despliegue conjunto la URL interna es <code>http://gastos-comida:8000</code>. El servicio está protegido para no arrancar con una base vacía: antes de activarlo hay que apuntar <code>GASTOS_DATA_DIR</code> a la carpeta que contiene tu <code>gastos.db</code> real.</div></section>';
h+='<section class="settings-card"><h2>🩺 Diagnóstico</h2><div class="settings-kv"><div>Versión</div><div>'+esc(s.version||"—")+'</div><div>Calendarios externos</div><div>'+esc(cal.subscription_count||0)+'</div><div>Documentos</div><div>'+esc(att.count||0)+'</div><div>Datos persistentes</div><div>'+esc(s.data_path||"data/")+'</div></div></section>';
h+='<section class="settings-card"><h2>🔒 Acceso</h2><div class="settings-warning">Casa Tareas no tiene autenticación de usuarios. Mantén la aplicación en una red privada de confianza, especialmente ahora que puede guardar un token de Telegram.</div></section>';
h+='<section class="settings-card wide"><h2>⚠️ Zona peligrosa</h2><div class="settings-warning">Estas acciones borran datos de forma permanente y no se pueden deshacer. Casa Tareas y Gastos se reinician por separado.</div><div class="settings-actions"><button class="danger" onclick="openDatabaseResetConfirm(\'casa\')">Borrar datos de Casa Tareas</button><button class="danger" onclick="openDatabaseResetConfirm(\'gastos\')">Borrar datos de Gastos</button></div><div class="settings-note"><strong>Casa Tareas:</strong> elimina tareas, áreas, personas, agenda, inventario, historial y adjuntos, pero conserva la configuración de la aplicación. <strong>Gastos:</strong> elimina tickets, líneas, productos y listas auxiliares, sin tocar Casa Tareas.</div></section>';
h+='</div>';document.getElementById("main").innerHTML=h}
async function saveTelegramTokenSetting(){var input=document.getElementById("telegramTokenSetting");var token=input?input.value.trim():"";if(!token){alert("Pega primero el token que te dio BotFather.");return}try{var r=await api("/api/settings/telegram-token",{method:"PUT",body:JSON.stringify({token:token})});if(input)input.value="";await load();view="settings";renderSettings();showUndo("Telegram configurado"+(r.telegram&&r.telegram.bot_username?" · @"+r.telegram.bot_username:""),null)}catch(e){alert(e.message)}}
async function deleteTelegramTokenSetting(){if(!confirm("¿Eliminar el token guardado en Casa Tareas? También se olvidará el grupo conectado y habrá que detectarlo de nuevo."))return;try{await api("/api/settings/telegram-token",{method:"DELETE"});await load();view="settings";renderSettings()}catch(e){alert(e.message)}}
async function saveRuntimeSettings(){var form=document.getElementById("runtimeSettingsForm");var f=new FormData(form);var o={timezone:String(f.get("timezone")||"").trim(),telegram_poll_seconds:Number(f.get("telegram_poll_seconds")),ical_sync_minutes:Number(f.get("ical_sync_minutes")),max_attachment_mb:Number(f.get("max_attachment_mb"))};try{await api("/api/settings/runtime",{method:"PUT",body:JSON.stringify(o)});await load();view="settings";renderSettings();showUndo("Configuración guardada",null)}catch(e){alert(e.message)}}
async function saveGastosIntegration(){var form=document.getElementById("gastosIntegrationForm");var f=new FormData(form);var url=String(f.get("url")||"").trim();try{await api("/api/settings/gastos-comida",{method:"PUT",body:JSON.stringify({url:url})});await load();view="settings";renderSettings();showUndo(url?"Integración de Gastos guardada":"Integración de Gastos desconectada",null)}catch(e){alert(e.message)}}
async function clearGastosIntegration(){var form=document.getElementById("gastosIntegrationForm");if(form){var input=form.querySelector('[name="url"]');if(input)input.value=""}await saveGastosIntegration()}
async function testGastosIntegration(){try{var r=await api("/api/integrations/gastos-comida/test",{method:"POST"});await load();view="settings";renderSettings();var h=r.health||{};showUndo("Conexión correcta · "+(h.products||0)+" productos · "+(h.tickets||0)+" tickets",null)}catch(e){await load();view="settings";renderSettings();alert(e.message)}}

function openDatabaseResetConfirm(kind){
  var isGastos=kind==="gastos";
  var title=isGastos?"Borrar base de Gastos":"Borrar datos de Casa Tareas";
  var body=isGastos
    ?"Se eliminarán definitivamente todos los tickets, artículos, productos y datos históricos de Gastos. Casa Tareas no se borrará."
    :"Se eliminarán definitivamente tareas, áreas, personas, agenda, inventario, historial y adjuntos. La configuración general se conservará y los ejemplos no volverán a crearse.";
  var html='<div class="modalhead"><div><h2>⚠️ '+esc(title)+'</h2><div class="muted">Esta acción no se puede deshacer.</div></div><button class="ghost" onclick="closeModal()">×</button></div><div class="settings-warning" style="margin-top:12px">'+esc(body)+'</div><div class="modalfoot"><button class="ghost" onclick="closeModal()">No, cancelar</button><button class="danger" onclick="confirmDatabaseReset(\''+kind+'\')">Sí, borrar</button></div>';
  showModal(html);
}
async function confirmDatabaseReset(kind){
  var isGastos=kind==="gastos";
  var url=isGastos?"/api/gastos/admin/reset":"/api/admin/reset-casa";
  var confirmation=isGastos?"BORRAR GASTOS":"BORRAR TAREAS";
  try{
    await api(url,{method:"POST",body:JSON.stringify({confirmation:confirmation})});
    closeModal();
    gastosDashboard=null;gastosTickets=[];gastosProducts=[];
    await load();
    view=isGastos?"gastos":"board";
    render();
    showUndo(isGastos?"Gastos se ha reiniciado desde cero":"Casa Tareas se ha reiniciado desde cero",null);
  }catch(e){alert(e.message)}
}

function renderHistory(){var h='<div class="pagehead"><div><h1>Historial</h1><div class="subtitle">Realizaciones y reparto de los últimos 30 días.</div></div></div><div class="stats">'+state.stats.map(function(s){return '<div class="stat"><div class="avatar" style="background:'+esc(s.color)+'">'+esc(s.icon)+'</div><div class="count">'+s.count+'</div><div>'+esc(s.name)+'</div><div class="muted">tareas · 30 días</div></div>'}).join("")+"</div>";h+='<div class="history">'+(state.history.length?state.history.map(function(x){return '<div class="hist"><div class="icon">'+esc(x.icon)+'</div><div><div class="title">'+esc(x.title)+'</div><div class="muted">'+new Date(x.completed_at).toLocaleString("es")+'</div></div><div class="avatar" style="background:'+esc(x.color)+'">'+esc(x.person_icon)+'</div></div>'}).join(""):'<div class="empty">Todavía no hay realizaciones.</div>')+"</div>";document.getElementById("main").innerHTML=h}
function showModal(html){document.getElementById("modal").innerHTML=html;document.getElementById("modal").classList.remove("hidden");document.getElementById("modalback").classList.remove("hidden")}
function closeModal(){var m=document.getElementById("modal");m.classList.add("hidden");m.classList.remove("gastos-ticket-modal");document.getElementById("modalback").classList.add("hidden")}
function activePeopleOptions(selected,emptyLabel){var h='<option value="">'+esc(emptyLabel||"Sin responsable")+'</option>';state.people.forEach(function(p){h+='<option value="'+p.id+'" '+(Number(selected)===p.id?"selected":"")+'>'+esc(p.icon)+" "+esc(p.name)+'</option>'});return h}
function activeAreaOptions(selected){var h='<option value="">Sin área</option>';state.areas.forEach(function(a){h+='<option value="'+a.id+'" '+(Number(selected)===a.id?"selected":"")+'>'+esc(a.icon)+" "+esc(a.name)+'</option>'});return h}
function openArea(id){var list=state.areas_all&&state.areas_all.length?state.areas_all:state.areas;var a=id?list.find(function(x){return x.id===id}):null;var html='<div class="modalhead"><div><h2>'+(a?"Editar área":"Nueva área")+'</h2><div class="muted">Quien sea responsable se encarga de detectar, planificar, ejecutar o coordinar y cerrar lo necesario.</div></div><button class="ghost" onclick="closeModal()">×</button></div><form id="areaform" class="formgrid"><div class="field full"><label>Nombre del área</label><input name="name" required maxlength="80" value="'+esc(a?a.name:"")+'"></div><div class="field full"><label>Qué incluye</label><textarea name="description" placeholder="Ej. planificación, compras, ejecución y reposición de consumibles">'+esc(a?a.description:"")+'</textarea></div><div class="field"><label>Icono</label><input name="icon" value="'+esc(a?a.icon:"🏠")+'"></div><div class="field"><label>Color</label><input name="color" type="color" value="'+esc(a?a.color:"#e7eefb")+'"></div><div class="field full"><label>Responsable total</label><select name="owner_person_id">'+activePeopleOptions(a&&a.owner_person_id?a.owner_person_id:null,"Sin responsable")+'</select></div></form>'+documentsBox("area",a)+'<div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveArea('+(a?a.id:"null")+')">Guardar</button></div>';showModal(html)}
async function saveArea(id){var f=new FormData(document.getElementById("areaform"));var o=Object.fromEntries(f.entries());o.owner_person_id=o.owner_person_id?Number(o.owner_person_id):null;try{await api(id?"/api/areas/"+id:"/api/areas",{method:id?"PUT":"POST",body:JSON.stringify(o)});closeModal();await load()}catch(e){alert(e.message)}}
async function archiveArea(id){var a=(state.areas_all||[]).find(function(x){return x.id===id});if(!confirm('¿Archivar el área "'+(a?a.name:"")+'"?\n\nLas tareas conservarán la referencia, pero dejarán de heredar su responsable hasta restaurarla o cambiar de área.'))return;try{var r=await api("/api/areas/"+id,{method:"DELETE"});await load();showUndo("Área archivada",r.undo_id)}catch(e){alert(e.message)}}
