async function deleteAreaPermanently(id){var a=(state.areas_all||[]).find(function(x){return x.id===id});if(!a)return;if((a.total_task_count||0)>0||(a.event_count||0)>0||(a.attachment_count||0)>0){alert("Mueve primero las tareas y eventos, y elimina los documentos asociados antes de borrar el área.");return}if(!confirm('Eliminar definitivamente el área "'+a.name+'"?\n\nEsta acción no se puede deshacer.'))return;try{await api("/api/areas/"+id+"/hard",{method:"DELETE"});await load()}catch(e){alert(e.message)}}
function openMoveTaskArea(taskId){var t=state.tasks.find(function(x){return x.id===taskId});if(!t)return;var html='<div class="modalhead"><div><h2>Mover tarea</h2><div class="muted">'+esc(t.title)+'</div></div><button class="ghost" onclick="closeModal()">×</button></div><div class="field"><label>Área de destino</label><select id="moveAreaSelect">'+activeAreaOptions(t.area_id)+'</select></div><div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="moveTaskArea('+taskId+',document.getElementById(\'moveAreaSelect\').value)">Mover</button></div>';showModal(html)}
async function moveTaskArea(taskId,areaId){var target=areaId===""||areaId==null?null:Number(areaId);try{var r=await api("/api/tasks/"+taskId+"/area",{method:"PUT",body:JSON.stringify({area_id:target})});closeModal();await load();if(r.undo_id)showUndo("Tarea movida de área",r.undo_id)}catch(e){alert(e.message)}}
function bindAreaDrag(){var mobile=window.matchMedia("(max-width:760px)").matches;document.querySelectorAll(".area-task[draggable=true]").forEach(function(el){if(mobile){el.setAttribute("draggable","false");return}el.addEventListener("dragstart",function(e){areaDraggedTask={id:Number(el.dataset.areaTaskId),current:el.dataset.currentArea===""?null:Number(el.dataset.currentArea)};el.style.opacity=".45";if(e.dataTransfer){e.dataTransfer.effectAllowed="move";e.dataTransfer.setData("text/plain",String(areaDraggedTask.id))}});el.addEventListener("dragend",function(){el.style.opacity="";areaDraggedTask=null;document.querySelectorAll(".area-drop").forEach(function(x){x.classList.remove("hot")})})});document.querySelectorAll(".area-drop").forEach(function(zone){zone.addEventListener("dragover",function(e){if(!areaDraggedTask||zone.dataset.areaActive!=="1")return;var target=zone.dataset.areaId===""?null:Number(zone.dataset.areaId);if(target===areaDraggedTask.current)return;e.preventDefault();zone.classList.add("hot")});zone.addEventListener("dragleave",function(e){if(!zone.contains(e.relatedTarget))zone.classList.remove("hot")});zone.addEventListener("drop",async function(e){if(!areaDraggedTask||zone.dataset.areaActive!=="1")return;var target=zone.dataset.areaId===""?null:Number(zone.dataset.areaId);if(target===areaDraggedTask.current)return;e.preventDefault();e.stopPropagation();zone.classList.remove("hot");var taskId=areaDraggedTask.id;areaDraggedTask=null;await moveTaskArea(taskId,target)})})}
function openPerson(id){var list=state.people_all&&state.people_all.length?state.people_all:state.people;var p=id?list.find(function(x){return x.id===id}):null;var html='<div class="modalhead"><div><h2>'+(p?"Editar persona":"Nueva persona")+'</h2><div class="muted">Nombre, icono y color para identificarla.</div></div><button class="ghost" onclick="closeModal()">×</button></div><form id="personform" class="formgrid"><div class="field full"><label>Nombre</label><input name="name" required maxlength="50" value="'+esc(p?p.name:"")+'"></div><div class="field"><label>Icono</label><input name="icon" value="'+esc(p?p.icon:"👤")+'"></div><div class="field"><label>Color</label><input name="color" type="color" value="'+esc(p?p.color:"#f7c8b6")+'"></div></form><div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="savePerson('+(p?p.id:"null")+')">Guardar</button></div>';showModal(html)}
