async function detectTelegramChats(){try{var r=await api("/api/telegram/chats",{method:"POST"});var chats=r.chats||[];var html='<div class="modalhead"><div><h2>Elegir chat de Telegram</h2><div class="muted">Si no aparece el grupo, envía /casa en él, espera unos segundos y vuelve a detectar.</div></div><button class="ghost" onclick="closeModal()">×</button></div>';if(!chats.length){html+='<div class="empty">No se han encontrado chats recientes.<br><br>Añade el bot al grupo, envía <strong>/casa</strong> y prueba de nuevo.</div><div class="modalfoot"><button class="primary" onclick="detectTelegramChats()">Volver a detectar</button></div>'}else{html+='<div>'+chats.map(function(ch){return'<div class="chat-choice"><div><strong>'+esc(ch.title)+'</strong><div class="chat-type">'+esc(ch.type)+' · '+esc(ch.chat_id)+'</div></div><button class="secondary" onclick="connectTelegramChat('+ch.chat_id+')">Usar este chat</button></div>'}).join("")+'</div>'}showModal(html)}catch(e){alert(e.message)}}
