var reminderPresets=[[10080,"7 días antes"],[1440,"1 día antes"],[120,"2 horas antes"],[60,"1 hora antes"],[30,"30 min antes"],[0,"A la hora"]];
function reminderOptions(selected){selected=selected||[1440];return reminderPresets.map(function(r){return'<label class="reminder-option"><input type="checkbox" name="reminder" value="'+r[0]+'" '+(selected.indexOf(r[0])>=0?"checked":"")+'> '+esc(r[1])+'</label>'}).join("")}
function openEvent(id){var e=id?(state.events||[]).find(function(x){return x.id===id}):null;var dt=e?datetimeLocalValue(e.event_at):datetimeLocalValue(null);var html='<div class="modalhead"><div><h2>'+(e?"Editar evento":"Nuevo evento")+'</h2><div class="muted">Para reuniones, citas, vencimientos y otras fechas concretas.</div></div><button class="ghost" onclick="closeModal()">×</button></div><form id="eventform" class="formgrid"><div class="field full"><label>Título</label><input name="title" required maxlength="160" value="'+esc(e?e.title:"")+'"></div><div class="field"><label>Área</label><select name="area_id">'+activeAreaOptions(e&&e.area_id?e.area_id:null)+'</select></div><div class="field"><label>Fecha y hora</label><input name="event_at" type="datetime-local" required value="'+esc(dt)+'"></div><div class="field full"><label>Notas</label><textarea name="description" placeholder="Documentación que llevar, dirección, temas a tratar…">'+esc(e?e.description:"")+'</textarea></div><div class="field full"><label>Avisarme</label><div class="reminders">'+reminderOptions(e?e.reminders:[1440])+'</div></div></form><div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveEvent('+(e?e.id:"null")+')">Guardar</button></div>';showModal(html)}
