function taskCategoryOptions(){var values=["General","Vacaciones-Viajes"];(state.tasks||[]).forEach(function(t){if(t.category&&values.indexOf(t.category)<0)values.push(t.category)});return values.sort(function(a,b){return a.localeCompare(b,"es")}).map(function(x){return '<option value="'+esc(x)+'"></option>'}).join("")}
function openTask(id){var t=id?state.tasks.find(function(x){return x.id===id}):null;var due=t&&t.initial_due_date?t.initial_due_date:new Date().toISOString().slice(0,10);var html='<div class="modalhead"><div><h2>'+(t?"Editar tarea":"Nueva tarea")+'</h2><div class="muted">La responsabilidad puede heredarse del área o sobrescribirse para esta tarea.</div></div><button class="ghost" onclick="closeModal()">×</button></div><form id="taskform" class="formgrid"><div class="field full"><label>Título</label><input name="title" required value="'+esc(t?t.title:"")+'"></div><div class="field full"><label>Descripción</label><textarea name="description">'+esc(t?t.description:"")+'</textarea></div><div class="field"><label>Categoría</label><input name="category" list="taskCategoryList" value="'+esc(t?t.category:"General")+'"><datalist id="taskCategoryList">'+taskCategoryOptions()+'</datalist></div><div class="field"><label>Área de responsabilidad</label><select name="area_id">'+activeAreaOptions(t&&t.area_id?t.area_id:null)+'</select></div><div class="field"><label>Tipo de trabajo</label><select name="task_type"><option value="execution">🧹 Ejecución</option><option value="management">🧠 Gestión / carga mental</option></select></div><div class="field"><label>Duración estimada</label><select name="estimated_minutes"><option value="">Sin estimar</option><option value="5">5 min</option><option value="10">10 min</option><option value="20">20 min</option><option value="30">30 min</option><option value="60">1 h</option><option value="90">1 h 30 min</option><option value="120">2 h</option></select></div><div class="field"><label>Responsable de esta tarea</label><select name="owner_person_id">'+activePeopleOptions(t&&t.owner_person_id?t.owner_person_id:null,"Heredar del área")+'</select></div><div class="field full"><label>Productos necesarios</label>'+taskSupplyPicker(t)+'</div><div class="field full"><label>Se considera terminada cuando…</label><textarea name="definition_of_done" placeholder="Ej. encimera y fregadero limpios, basura revisada y productos guardados">'+esc(t?t.definition_of_done:"")+'</textarea></div><div class="field full"><label>Notas de responsabilidad</label><textarea name="responsibility_notes" placeholder="Ej. incluye comprobar consumibles y decidir cuándo hacerlo">'+esc(t?t.responsibility_notes:"")+'</textarea></div><div class="field"><label>Icono</label><input name="icon" value="'+esc(t?t.icon:"🧹")+'"></div><div class="field"><label>Color</label><input name="color" type="color" value="'+esc(t?t.color:"#dcecff")+'"></div><div class="field"><label>Recurrencia</label><select name="recurrence_type"><option value="none">Puntual</option><option value="cycle">Cada X días desde última vez</option><option value="fixed">Calendario fijo</option></select></div><div class="field"><label>Cada X días</label><input name="frequency_days" type="number" min="1" value="'+esc(t&&t.frequency_days?t.frequency_days:"7")+'"></div><div class="field"><label>Primera / próxima fecha</label><input name="initial_due_date" type="date" value="'+esc(due)+'"></div><div class="field"><label>Fecha de anclaje</label><input name="anchor_date" type="date" value="'+esc(t&&t.anchor_date?t.anchor_date:due)+'"></div></form>'+documentsBox("task",t)+'<div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveTask('+(t?t.id:"null")+')">Guardar</button></div>';showModal(html);document.querySelector('[name="recurrence_type"]').value=t?t.recurrence_type:"cycle";document.querySelector('[name="task_type"]').value=t&&t.task_type?t.task_type:"execution";document.querySelector('[name="estimated_minutes"]').value=t&&t.estimated_minutes?String(t.estimated_minutes):""}

