function postpone(id){var tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);var d=tomorrow.toISOString().slice(0,10);var html='<div class="modalhead"><div><h2>Posponer</h2><div class="muted">Solo cambia esta aparición.</div></div><button class="ghost" onclick="closeModal()">×</button></div><div class="field"><label>Nueva fecha</label><input id="postdate" type="date" value="'+d+'"></div><div class="modalfoot"><button class="ghost" onclick="closeModal()">Cancelar</button><button class="primary" onclick="doPostpone('+id+')">Guardar</button></div>';showModal(html)}
async function doPostpone(id){var d=document.getElementById("postdate").value;try{var r=await api("/api/tasks/"+id+"/postpone",{method:"POST",body:JSON.stringify({due_date:d})});closeModal();await load();showUndo("Tarea pospuesta",r.undo_id)}catch(e){alert(e.message)}}
function bindBoardDrag(){if(window.matchMedia("(max-width:760px)").matches){document.querySelectorAll('.kanban [draggable="true"]').forEach(function(el){el.setAttribute("draggable","false")});return}document.querySelectorAll('.kanban [draggable="true"]').forEach(function(el){el.addEventListener("dragstart",function(e){if(dropBusy){e.preventDefault();return}dragged={id:Number(el.dataset.id),origin:el.dataset.origin,completionId:el.dataset.completionId?Number(el.dataset.completionId):null};el.style.opacity=".45";if(e.dataTransfer){e.dataTransfer.effectAllowed="move";e.dataTransfer.setData("text/plain",String(dragged.id))}});el.addEventListener("dragend",function(){el.style.opacity="";document.querySelectorAll(".kanban-col").forEach(function(x){x.classList.remove("hot")});if(!dropBusy)dragged=null});el.addEventListener("dragover",function(e){if(dragged&&dragged.origin==="today"&&el.dataset.origin==="today"){e.preventDefault();e.stopPropagation()}});el.addEventListener("drop",async function(e){if(dropBusy||!dragged||dragged.origin!=="today"||el.dataset.origin!=="today")return;e.preventDefault();e.stopPropagation();var target=Number(el.dataset.id);if(dragged.id===target)return;var ids=state.today.map(function(t){return t.id});var a=ids.indexOf(dragged.id),b=ids.indexOf(target);if(a<0||b<0)return;ids.splice(a,1);ids.splice(b,0,dragged.id);dropBusy=true;try{var r=await api("/api/today/reorder",{method:"POST",body:JSON.stringify({task_ids:ids})});dragged=null;await load();if(r.undo_id)showUndo("Orden de Hoy cambiado",r.undo_id)}catch(err){alert(err.message)}finally{dropBusy=false}})});document.querySelectorAll(".kanban-col").forEach(function(col){col.addEventListener("dragover",function(e){if(dropBusy||!dragged)return;var target=col.dataset.drop;if((target==="today"&&(dragged.origin==="upcoming"||dragged.origin==="done"))||(target==="upcoming"&&dragged.origin==="today")||(target==="done"&&dragged.origin==="today")){e.preventDefault();col.classList.add("hot")}});col.addEventListener("dragleave",function(e){if(!col.contains(e.relatedTarget))col.classList.remove("hot")});col.addEventListener("drop",async function(e){if(dropBusy||!dragged)return;var target=col.dataset.drop;if(!((target==="today"&&(dragged.origin==="upcoming"||dragged.origin==="done"))||(target==="upcoming"&&dragged.origin==="today")||(target==="done"&&dragged.origin==="today")))return;e.preventDefault();e.stopPropagation();col.classList.remove("hot");var item={id:dragged.id,origin:dragged.origin,completionId:dragged.completionId};dragged=null;dropBusy=true;try{if(target==="today"){if(item.origin==="done"){var r=await api("/api/completions/"+item.completionId+"/undo-to-today",{method:"POST"});await load();showUndo('Realización deshecha · "'+(r.task_title||"Tarea")+'" vuelve a Hoy',null)}else{var r=await api("/api/today/"+item.id,{method:"POST"});await load();if(r.undo_id)showUndo("Añadida a Hoy",r.undo_id)}}else if(target==="upcoming"){var r=await api("/api/today/"+item.id,{method:"DELETE"});await load();if(r.undo_id)showUndo("Quitada de Hoy",r.undo_id)}else if(target==="done"){completeTask(item.id)}}catch(err){alert(err.message)}finally{dropBusy=false}})})}

function mobileColumnName(i){return ["Todas las tareas","Próximamente","Hoy","Realizadas"][i]||""}
function updateMobileBoardIndicator(){var label=document.getElementById("mobileBoardLabel"),pos=document.getElementById("mobileBoardPos");if(label)label.textContent=mobileColumnName(mobileBoardIndex);if(pos)pos.textContent=(mobileBoardIndex+1)+" / 4"}
function moveBoard(delta){var board=document.getElementById("kanbanBoard");if(!board)return;var cols=board.querySelectorAll(".kanban-col");mobileBoardIndex=Math.max(0,Math.min(cols.length-1,mobileBoardIndex+delta));var target=cols[mobileBoardIndex];board.scrollTo({left:target.offsetLeft,behavior:"smooth"});updateMobileBoardIndicator()}
function initMobileBoard(){if(!window.matchMedia("(max-width:760px)").matches)return;var board=document.getElementById("kanbanBoard");if(!board)return;var cols=board.querySelectorAll(".kanban-col");mobileBoardIndex=Math.max(0,Math.min(cols.length-1,mobileBoardIndex));requestAnimationFrame(function(){board.scrollLeft=cols[mobileBoardIndex].offsetLeft;updateMobileBoardIndicator()});board.addEventListener("scroll",function(){if(boardScrollRAF)cancelAnimationFrame(boardScrollRAF);boardScrollRAF=requestAnimationFrame(function(){var best=0,dist=Infinity;cols.forEach(function(col,i){var d=Math.abs(col.offsetLeft-board.scrollLeft);if(d<dist){dist=d;best=i}});if(best!==mobileBoardIndex){mobileBoardIndex=best;updateMobileBoardIndicator()}})},{passive:true})}

load();
